sp_widget.client_script:
api.controller=function() {
 c.bookRequests = c.data.bookRequests;
    c.title = c.data.title;

    // Refresh book requests (optional feature for dynamic updates)
    c.refreshBookRequests = function() {
        $http.get('/api/now/table/sn_lms_book_requests').then(function(response) {
            c.bookRequests = response.data.result; // Update with refreshed data
        });
    };
};

sp_widget.link:
function link(scope, element, attrs, controller) {
  angular.module('sn.$sp').directive('bookRequestsWidget', function() {
    return {
        restrict: 'A',
        link: function(scope, element, attrs) {
            // Add hover effect for table rows
            element.find('tr').on('mouseenter', function() {
                angular.element(this).addClass('hover-highlight');
            });

            element.find('tr').on('mouseleave', function() {
                angular.element(this).removeClass('hover-highlight');
            });

            // Add event listener for a "details" button (if applicable)
            element.find('.details-btn').on('click', function() {
                alert('Details clicked for: ' + angular.element(this).data('bookTitle'));
            });
        }
    };
});

}

sp_widget.script:
(function() {
    // Fetch the current logged-in user
    var userId = gs.getUserID();

    // Query the book request records for the logged-in user
    var bookRequestsGR = new GlideRecord('sn_lms_book_requests');
    bookRequestsGR.addQuery('user_id', userId);
    bookRequestsGR.orderByDesc('sys_created_on');
    bookRequestsGR.query();

    // Populate data for the widget
    data.bookRequests = [];
    while (bookRequestsGR.next()) {
        data.bookRequests.push({
            sys_id: bookRequestsGR.sys_id,
           // title: bookRequestsGR.getValue('u_book_title'),
            status: bookRequestsGR.status,
            return_date: bookRequestsGR.return_date
        });
    }

    // Additional information for the widget
    data.title = "My Book Requests";
})();
